import {FISH} from './fish-config.js';import {fishCount,fishSupply,fishCanStock} from './fish-state.js';import {fishReady,addFishStock,fishReceipt} from './fish-stock.js';import {cowEffectiveGrade} from './cow-storage.js';import {cowMilkingReason} from './cow-milking.js';import {goatContractReason} from './goat-market-policy.js';
/** Genuine immediately marketable alternatives must be used before restricted aid. @param {import('./engine.js').State} s */
function saleable(s){return !!(s.inventory.length||s.plots.some(p=>p.crop?.progress===1)||s.chicken?.inventory.length||s.cow?.lots.some(l=>!!cowEffectiveGrade(l))||s.cow?.cows.some(c=>!cowMilkingReason(s,c.id,'can'))||s.goat?.herd.some(h=>!goatContractReason(s,h.id))||s.fish?.lots.length||s.fish?.ponds.some(p=>p.cohorts.some(c=>fishReady(c,s.tick))));}
/** @param {import('./engine.js').State} state @param {boolean} [claim] */
export function fishRecoveryReason(state,claim=false){const g=state.fish;if(!g?.visited)return 'fishNotVisited';if(!claim&&g.recovery.active)return 'fishJobActive';if(!claim&&state.tick<g.recovery.lastCompletedTick+24)return 'fishJobCooldown';if(saleable(state))return 'fishRecoverySellFirst';const count=g.ponds.reduce((n,p)=>n+fishCount(p),0);if(!count){if(g.recovery.advanceCoins)return 'fishAdvanceOutstanding';if(state.coins>=FISH.fingerlingCoins)return 'fishRecoveryNotNeeded';return '';}
 const feed=fishSupply(g.feed)+g.ponds.reduce((n,p)=>n+p.pendingFeedG,0),air=g.air.starter+g.air.recovery+g.ponds.reduce((n,p)=>n+p.airPaidTicks,0);const shortage=state.coins<FISH.feedBagCoins&&feed<Math.min(1000,count*48)||state.coins<FISH.exchangeCoins&&fishSupply(g.water)<200||state.coins<FISH.airCoins&&air===0;if(shortage)return '';return g.feed.recovery||g.water.recovery||g.air.recovery?'fishRecoveryUseAid':'fishRecoveryNotNeeded';}
/** @param {import('./engine.js').State} state @returns {string|undefined} */
export function startFishRecovery(state){const reason=fishRecoveryReason(state);if(reason)return reason;const g=state.fish;if(!g)return 'fishNotVisited';const j=g.recovery;j.active=true;j.mode=g.ponds.some(p=>fishCount(p)>0)?'care':'restock';j.startedTick=state.tick;j.episode++;}
/** Earned, source-tagged, nontradable net shortfalls only; never Coins. @param {import('./engine.js').State} state @returns {string|undefined} */
export function claimFishRecovery(state){const g=state.fish;if(!g)return 'fishNotVisited';const j=g.recovery;if(!j.active)return 'fishJobMissing';const hours=j.mode==='restock'?FISH.restockWorkHours:FISH.recoveryHours;if(state.tick-j.startedTick<hours)return 'fishJobWorking';const needed=!fishRecoveryReason(state,true);if(needed&&j.mode==='restock'){const p=g.ponds[0];if(!fishCanStock(p,1)||j.advanceCoins)return 'fishAdvanceOutstanding';j.advanceCount++;j.advanceCoins+=FISH.fingerlingCoins;addFishStock(state,p,1,'advance');fishReceipt(g,state.tick,'advance',p.id,1,FISH.fingerlingG,FISH.fingerlingCoins);}j.active=false;j.completed++;j.lastCompletedTick=state.tick;if(needed){const count=g.ponds.reduce((n,p)=>n+fishCount(p),0),feed=Math.max(0,Math.min(1000,count*48)-fishSupply(g.feed)-g.ponds.reduce((n,p)=>n+p.pendingFeedG,0)),water=Math.max(0,200-fishSupply(g.water)),air=Math.max(0,24-g.air.starter-g.air.recovery-g.ponds.reduce((n,p)=>n+p.airPaidTicks,0));g.feed.recovery+=feed;g.water.recovery+=water;g.air.recovery+=air;g.stats.recoveryFeedGrantedG+=feed;g.stats.recoveryWaterGrantedL+=water;g.stats.recoveryAirGrantedTicks+=air;}fishReceipt(g,state.tick,'recovery',1);}
